// Hash Generator - MD5, SHA-1, SHA-256
// Pure JavaScript implementations

var text = input.get("text");
var algorithm = input.get("algorithm") || "SHA-256";
var outputFormat = input.get("outputFormat") || "hex";

// MD5 Implementation
function md5(str) {
    function rotateLeft(x, n) { return (x << n) | (x >>> (32 - n)); }
    function addUnsigned(x, y) {
        var x4 = (x & 0x40000000), y4 = (y & 0x40000000);
        var x8 = (x & 0x80000000), y8 = (y & 0x80000000);
        var result = (x & 0x3FFFFFFF) + (y & 0x3FFFFFFF);
        if (x4 & y4) return (result ^ 0x80000000 ^ x8 ^ y8);
        if (x4 | y4) {
            if (result & 0x40000000) return (result ^ 0xC0000000 ^ x8 ^ y8);
            else return (result ^ 0x40000000 ^ x8 ^ y8);
        } else return (result ^ x8 ^ y8);
    }
    function F(x,y,z) { return (x & y) | ((~x) & z); }
    function G(x,y,z) { return (x & z) | (y & (~z)); }
    function H(x,y,z) { return (x ^ y ^ z); }
    function I(x,y,z) { return (y ^ (x | (~z))); }
    function FF(a,b,c,d,x,s,ac) { a = addUnsigned(a, addUnsigned(addUnsigned(F(b,c,d), x), ac)); return addUnsigned(rotateLeft(a, s), b); }
    function GG(a,b,c,d,x,s,ac) { a = addUnsigned(a, addUnsigned(addUnsigned(G(b,c,d), x), ac)); return addUnsigned(rotateLeft(a, s), b); }
    function HH(a,b,c,d,x,s,ac) { a = addUnsigned(a, addUnsigned(addUnsigned(H(b,c,d), x), ac)); return addUnsigned(rotateLeft(a, s), b); }
    function II(a,b,c,d,x,s,ac) { a = addUnsigned(a, addUnsigned(addUnsigned(I(b,c,d), x), ac)); return addUnsigned(rotateLeft(a, s), b); }
    function toWordArray(str) {
        var len = str.length, words = [], i;
        for (i = 0; i < len; i++) words[i >> 2] |= (str.charCodeAt(i) & 0xFF) << ((i % 4) * 8);
        words[len >> 2] |= 0x80 << ((len % 4) * 8);
        words[(((len + 8) >> 6) << 4) + 14] = len * 8;
        return words;
    }
    function toHex(n) {
        var hex = '', i;
        for (i = 0; i < 4; i++) hex += ((n >> (i * 8 + 4)) & 0xF).toString(16) + ((n >> (i * 8)) & 0xF).toString(16);
        return hex;
    }
    var x = toWordArray(str), a = 0x67452301, b = 0xEFCDAB89, c = 0x98BADCFE, d = 0x10325476;
    var S = [7,12,17,22, 5,9,14,20, 4,11,16,23, 6,10,15,21];
    var T = [0xD76AA478,0xE8C7B756,0x242070DB,0xC1BDCEEE,0xF57C0FAF,0x4787C62A,0xA8304613,0xFD469501,0x698098D8,0x8B44F7AF,0xFFFF5BB1,0x895CD7BE,0x6B901122,0xFD987193,0xA679438E,0x49B40821,0xF61E2562,0xC040B340,0x265E5A51,0xE9B6C7AA,0xD62F105D,0x02441453,0xD8A1E681,0xE7D3FBC8,0x21E1CDE6,0xC33707D6,0xF4D50D87,0x455A14ED,0xA9E3E905,0xFCEFA3F8,0x676F02D9,0x8D2A4C8A,0xFFFA3942,0x8771F681,0x6D9D6122,0xFDE5380C,0xA4BEEA44,0x4BDECFA9,0xF6BB4B60,0xBEBFBC70,0x289B7EC6,0xEAA127FA,0xD4EF3085,0x04881D05,0xD9D4D039,0xE6DB99E5,0x1FA27CF8,0xC4AC5665,0xF4292244,0x432AFF97,0xAB9423A7,0xFC93A039,0x655B59C3,0x8F0CCC92,0xFFEFF47D,0x85845DD1,0x6FA87E4F,0xFE2CE6E0,0xA3014314,0x4E0811A1,0xF7537E82,0xBD3AF235,0x2AD7D2BB,0xEB86D391];
    for (var k = 0; k < x.length; k += 16) {
        var AA = a, BB = b, CC = c, DD = d;
        for (var i = 0; i < 64; i++) {
            var g, f;
            if (i < 16) { f = F(b,c,d); g = i; }
            else if (i < 32) { f = G(b,c,d); g = (5*i + 1) % 16; }
            else if (i < 48) { f = H(b,c,d); g = (3*i + 5) % 16; }
            else { f = I(b,c,d); g = (7*i) % 16; }
            var temp = d; d = c; c = b;
            b = addUnsigned(b, rotateLeft(addUnsigned(a, addUnsigned(addUnsigned(f, x[k+g] || 0), T[i])), S[(i>>4)*4 + (i%4)]));
            a = temp;
        }
        a = addUnsigned(a, AA); b = addUnsigned(b, BB); c = addUnsigned(c, CC); d = addUnsigned(d, DD);
    }
    return toHex(a) + toHex(b) + toHex(c) + toHex(d);
}

// SHA-1 Implementation
function sha1(str) {
    function rotl(n, s) { return (n << s) | (n >>> (32 - s)); }
    function toHex32(val) {
        var hex = '';
        for (var i = 7; i >= 0; i--) hex += ((val >>> (i * 4)) & 0xF).toString(16);
        return hex;
    }
    var msg = [];
    for (var i = 0; i < str.length; i++) msg.push(str.charCodeAt(i) & 0xFF);
    msg.push(0x80);
    var len = msg.length;
    while ((msg.length % 64) !== 56) msg.push(0);
    var bits = (str.length * 8);
    msg.push(0, 0, 0, 0, (bits >>> 24) & 0xFF, (bits >>> 16) & 0xFF, (bits >>> 8) & 0xFF, bits & 0xFF);
    var h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476, h4 = 0xC3D2E1F0;
    for (var chunk = 0; chunk < msg.length; chunk += 64) {
        var w = [];
        for (var i = 0; i < 16; i++) {
            w[i] = (msg[chunk + i*4] << 24) | (msg[chunk + i*4 + 1] << 16) | (msg[chunk + i*4 + 2] << 8) | msg[chunk + i*4 + 3];
        }
        for (var i = 16; i < 80; i++) {
            w[i] = rotl(w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16], 1);
        }
        var a = h0, b = h1, c = h2, d = h3, e = h4;
        for (var i = 0; i < 80; i++) {
            var f, k;
            if (i < 20) { f = (b & c) | ((~b) & d); k = 0x5A827999; }
            else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
            else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
            else { f = b ^ c ^ d; k = 0xCA62C1D6; }
            var temp = (rotl(a, 5) + f + e + k + w[i]) | 0;
            e = d; d = c; c = rotl(b, 30); b = a; a = temp;
        }
        h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0; h4 = (h4 + e) | 0;
    }
    return toHex32(h0) + toHex32(h1) + toHex32(h2) + toHex32(h3) + toHex32(h4);
}

// SHA-256 Implementation
function sha256(str) {
    function rotr(n, x) { return (x >>> n) | (x << (32 - n)); }
    function ch(x, y, z) { return (x & y) ^ (~x & z); }
    function maj(x, y, z) { return (x & y) ^ (x & z) ^ (y & z); }
    function sig0(x) { return rotr(2, x) ^ rotr(13, x) ^ rotr(22, x); }
    function sig1(x) { return rotr(6, x) ^ rotr(11, x) ^ rotr(25, x); }
    function gam0(x) { return rotr(7, x) ^ rotr(18, x) ^ (x >>> 3); }
    function gam1(x) { return rotr(17, x) ^ rotr(19, x) ^ (x >>> 10); }
    function toHex32(val) {
        var hex = '';
        for (var i = 7; i >= 0; i--) hex += ((val >>> (i * 4)) & 0xF).toString(16);
        return hex;
    }
    var K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
    var h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    var msg = [];
    for (var i = 0; i < str.length; i++) msg.push(str.charCodeAt(i) & 0xFF);
    msg.push(0x80);
    while ((msg.length % 64) !== 56) msg.push(0);
    var bits = str.length * 8;
    msg.push(0, 0, 0, 0, (bits >>> 24) & 0xFF, (bits >>> 16) & 0xFF, (bits >>> 8) & 0xFF, bits & 0xFF);
    for (var chunk = 0; chunk < msg.length; chunk += 64) {
        var w = [];
        for (var i = 0; i < 16; i++) {
            w[i] = (msg[chunk + i*4] << 24) | (msg[chunk + i*4 + 1] << 16) | (msg[chunk + i*4 + 2] << 8) | msg[chunk + i*4 + 3];
        }
        for (var i = 16; i < 64; i++) {
            w[i] = (gam1(w[i-2]) + w[i-7] + gam0(w[i-15]) + w[i-16]) | 0;
        }
        var a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
        for (var i = 0; i < 64; i++) {
            var t1 = (hh + sig1(e) + ch(e,f,g) + K[i] + w[i]) | 0;
            var t2 = (sig0(a) + maj(a,b,c)) | 0;
            hh=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
        }
        h[0]=(h[0]+a)|0; h[1]=(h[1]+b)|0; h[2]=(h[2]+c)|0; h[3]=(h[3]+d)|0;
        h[4]=(h[4]+e)|0; h[5]=(h[5]+f)|0; h[6]=(h[6]+g)|0; h[7]=(h[7]+hh)|0;
    }
    return h.map(toHex32).join('');
}

function hexToBase64(hex) {
    var bytes = [];
    for (var i = 0; i < hex.length; i += 2) bytes.push(parseInt(hex.substr(i, 2), 16));
    var b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    var result = '';
    for (var i = 0; i < bytes.length; i += 3) {
        var b1 = bytes[i], b2 = bytes[i+1] || 0, b3 = bytes[i+2] || 0;
        result += b64chars[(b1 >> 2)];
        result += b64chars[((b1 & 3) << 4) | (b2 >> 4)];
        result += (i+1 < bytes.length) ? b64chars[((b2 & 15) << 2) | (b3 >> 6)] : '=';
        result += (i+2 < bytes.length) ? b64chars[b3 & 63] : '=';
    }
    return result;
}

if (!text && text !== "") {
    log.error("Text input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Text input is required");
    output.set("Hash", "");
    tags.trigger("error");
} else {
    try {
        var hash = "";

        switch (algorithm.toUpperCase()) {
            case "MD5":
                hash = md5(text);
                break;
            case "SHA-1":
            case "SHA1":
                hash = sha1(text);
                break;
            case "SHA-256":
            case "SHA256":
            default:
                hash = sha256(text);
                break;
        }

        var result = hash;
        if (outputFormat === "base64") {
            result = hexToBase64(hash);
        } else if (outputFormat === "uppercase") {
            result = hash.toUpperCase();
        }

        output.set("Hash", result);
        output.set("HashHex", hash);
        output.set("HashBase64", hexToBase64(hash));
        output.set("Algorithm", algorithm);
        output.set("InputLength", text.length);
        output.set("HashLength", hash.length);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");

        log.info(algorithm + " hash generated: " + hash.substring(0, 16) + "...");
        tags.trigger("success");

    } catch (ex) {
        log.error("Hash generation failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Hash", "");
        tags.trigger("error");
    }
}
